const input = $json;

// Soporta tres origenes posibles:
// - Execute Workflow del Manager: { traceId, channel, sender, message, intent, fecha_inicio, fecha_fin, tipo, categoria, ocupacion, payload? }
// - Webhook directo: { body: { ... } }
// - Chat Trigger: { chatInput, sessionId }
const data = input.body ?? input;

const traceId = String(
  input.traceId ?? data.traceId ?? ''
).trim();

const message = String(
  data.message ??
  data.text ??
  data.chatInput ??
  ''
).trim();

const channel = String(
  data.channel ??
  (input.sessionId ? 'chat' : 'unknown')
).trim();

const sender = String(
  data.sender ??
  data.from ??
  input.sessionId ??
  'unknown'
).trim();

const intent = String(
  data.intent ?? input.intent ?? ''
).trim().toUpperCase();

// ---------- Fechas ----------
const fechaInicioRaw =
  String(
    input.payload?.fechas?.fecha_inicio ??
    input.payload?.fecha_inicio ??
    input.fecha_inicio ??
    data.fecha_inicio ??
    ''
  ).trim() || null;

const fechaFinRaw =
  String(
    input.payload?.fechas?.fecha_fin ??
    input.payload?.fecha_fin ??
    input.fecha_fin ??
    data.fecha_fin ??
    ''
  ).trim() || null;

const tipoFecha =
  input.payload?.fechas?.tipo ??
  input.tipo ??
  (fechaInicioRaw ? 'una_noche' : 'sin_fechas');

const categoria =
  input.payload?.fechas?.categoria ??
  input.categoria ??
  null;

const ocupacion = Number(
  input.payload?.fechas?.ocupacion ??
  input.ocupacion ??
  1
) || 1;

const payload = {
  fechas: {
    tipo: tipoFecha,
    fecha_inicio: fechaInicioRaw,
    fecha_fin: fechaFinRaw,
    categoria,
    ocupacion
  }
};

// ---------- Validaciones ----------
let valid = true;
const errors = [];

if (!traceId) {
  valid = false;
  errors.push('Falta traceId');
}

if (!message) {
  valid = false;
  errors.push('Falta message');
}

if (!channel) {
  valid = false;
  errors.push('Falta channel');
}

if (!sender) {
  valid = false;
  errors.push('Falta sender');
}

if (intent !== 'DISPONIBILIDAD') {
  valid = false;
  errors.push('Intent invalido para Worker Disponibilidad');
}

return {
  json: {
    traceId,
    timestamp: new Date().toISOString(),

    channel,
    sender,
    message,
    intent,

    payload,

    validation: {
      valid,
      errors
    }
  }
};

// 05 - Preparar Resultado
const sheets = $('04b - Parsear Sheets').first().json;
const rows = sheets.disponibilidad;
const tarifasRows = sheets.tarifas;
const ctx = $('02 - Validar Entrada').first().json;

// ---------- Utils ----------
const toISO = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  return null;
};

const addDays = (iso, n) => {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};

const categoriaDeHabitacion = (id) => {
  const prefijo = String(id).split('-')[0].toUpperCase();
  const mapa = { STD: 'STANDARD', SUP: 'SUPERIOR', PRE: 'PREMIUM' };
  return mapa[prefijo] ?? null;
};

// ---------- Fechas ----------
const fechas = ctx.payload?.fechas ?? {};
const fechaInicio = toISO(fechas.fecha_inicio);
const fechaFin = toISO(fechas.fecha_fin);
const tipoFecha = fechas.tipo ?? 'sin_fechas';
const categoriaSolicitada = fechas.categoria ?? null;
const ocupacion = Number(fechas.ocupacion ?? 1) || 1;

const hoy = new Date(Date.now() - 3 * 60 * 60 * 1000).toISOString().slice(0, 10);

// ---------- Noches ----------
const noches = [];
if (fechaInicio) {
  if (!fechaFin || fechaFin <= fechaInicio) {
    noches.push(fechaInicio);
  } else {
    for (let d = fechaInicio; d < fechaFin && noches.length < 90; d = addDays(d, 1)) {
      noches.push(d);
    }
  }
}

// ---------- Disponibilidad ----------
const estadoPorNoche = {};
const habitaciones = new Set();
for (const r of rows) {
  const f = toISO(r.fecha);
  const id = String(r.habitacion_id ?? '').trim();
  if (!f || !id) continue;
  habitaciones.add(id);
  (estadoPorNoche[f] ??= {})[id] = String(r.estado ?? '').trim().toUpperCase();
}

const fechasSinDatos = noches.filter(n => !estadoPorNoche[n]);
const habitacionesDisponibles = [...habitaciones].filter(id =>
  noches.length > 0 &&
  noches.every(n => estadoPorNoche[n]?.[id] === 'DISPONIBLE')
);

// ---------- Tarifas ----------
const tarifasPorCategoria = {};
for (const t of tarifasRows) {
  const cat = String(t.categoria ?? '').trim().toUpperCase();
  if (!cat) continue;
  tarifasPorCategoria[cat] = {
    precioBase: Number(t.precio_base),
    precioExtra: Number(t.precio_extra_persona),
    capacidadMax: Number(t.capacidad_max)
  };
}

// ---------- Categorias disponibles ----------
const categoriasUnicas = [...new Set(
  habitacionesDisponibles.map(categoriaDeHabitacion).filter(Boolean)
)];

const categoriasDisponibles = categoriasUnicas.map(cat => {
  const t = tarifasPorCategoria[cat];
  if (!t) return null;

  const apta = ocupacion <= t.capacidadMax;
  const precioNoche =
    t.precioBase + Math.max(0, ocupacion - 1) * t.precioExtra;
  const precioTotal = precioNoche * Math.max(1, noches.length);

  return {
    categoria: cat,
    precio_noche: precioNoche,
    precio_total: precioTotal,
    capacidad_max: t.capacidadMax,
    apta
  };
}).filter(Boolean);

// ---------- Output ----------
return [{
  json: {
    traceId: ctx.traceId,
    timestamp: ctx.timestamp,
    channel: ctx.channel,
    sender: ctx.sender,
    message: ctx.message,
    intent: ctx.intent,
    payload: {
      fechas: {
        tipo: tipoFecha,
        fecha_inicio: fechaInicio,
        fecha_fin: fechaFin,
        categoria: categoriaSolicitada,
        ocupacion
      }
    },

    result: {
      faltanFechas: !fechaInicio,
      fechaPasada: !!fechaInicio && fechaInicio < hoy,
      fechaInicio,
      fechaFin,
      cantidadNoches: noches.length,
      ocupacion,
      categoriaSolicitada,
      fechasSinDatos,
      habitacionesDisponibles,
      cantidadDisponibles: habitacionesDisponibles.length,
      categoriasDisponibles
    }
  }
}];

