const resultado = $('05 - Preparar Resultado').first().json;
const respuesta = $('06 - Generar Respuesta').first().json;
const judge = $('07 - Judge').first().json.output;

const texto = String(respuesta.text ?? '').trim();
const responseFinal = texto.length > 0
  ? texto
  : 'No pudimos procesar tu consulta en este momento. Por favor, intentá de nuevo o contactá a recepción.';

return [
  {
    json: {
      traceId: resultado.traceId,
      timestamp: resultado.timestamp,

      channel: resultado.channel,
      sender: resultado.sender,
      message: resultado.message,
      intent: resultado.intent,

      approved: judge.approved,

      response: responseFinal,

      worker: {
        workflow: 'WF_WORKER_DISPONIBILIDAD',
        stage: 'RESPUESTA_FINAL'
      },

      judge: judge
    }
  }
];

const input = $json;

return [
  {
    json: {
      status: 'RECHAZADO',
      approved: false,

      error: {
        code: 'INVALID_WORKER_INPUT',
        message: 'La entrada recibida por el Worker no cumple con los campos requeridos.'
      },

      traceId: input.traceId ?? null,
      timestamp: new Date().toISOString(),

      worker: {
        workflow: 'WF_WORKER_DISPONIBILIDAD',
        stage: 'VALIDACION_ENTRADA'
      }
    }
  }
];

const judge = $('07 - Judge').first().json.output;

// traceId puede venir de 05, o de 02 si 05 no se ejecutó
let traceId = null;
try {
  traceId = $('05 - Preparar Resultado').first().json.traceId;
} catch (e) {
  try {
    traceId = $('02 - Validar Entrada').first().json.traceId;
  } catch (e2) {
    traceId = null;
  }
}

return [
  {
    json: {
      status: 'BLOQUEADO',
      approved: false,

      response: null,

      traceId,
      timestamp: new Date().toISOString(),

      judge,

      escalation: {
        required: true,
        reason: judge?.reason ?? 'La respuesta no superó las validaciones de seguridad.'
      },

      worker: {
        workflow: 'WF_WORKER_DISPONIBILIDAD',
        stage: 'ACTION_GATE'
      }
    }
  }
];

// 04b - Parsear Sheets
// Convierte la respuesta de batchGet (arrays de arrays) a objetos

const response = $json;
const ranges = response.valueRanges ?? [];

// Convierte [["a","b"],["1","2"]] a [{a:"1",b:"2"}]
const rowsToObjects = (values) => {
  if (!values || values.length < 2) return [];
  const headers = values[0].map(h => String(h).trim().toLowerCase());
  return values.slice(1).map(row => {
    const obj = {};
    headers.forEach((h, i) => {
      obj[h] = row[i] ?? null;
    });
    return obj;
  });
};

// Identifica cada rango por nombre
const dispRange = ranges.find(r =>
  String(r.range ?? '').toUpperCase().startsWith('DISPONIBILIDAD')
);
const tarRange = ranges.find(r =>
  String(r.range ?? '').toUpperCase().startsWith('TARIFAS')
);

const disponibilidad = rowsToObjects(dispRange?.values ?? []);
const tarifas = rowsToObjects(tarRange?.values ?? []);

return {
  json: {
    disponibilidad,
    tarifas,
    _meta: {
      disponibilidadRows: disponibilidad.length,
      tarifasRows: tarifas.length
    }
  }
};
